import React,{useState,useRef,useEffect,useCallback} from 'react';
import {relationSidebarWidth,relationSidebarKey,relationSidebarLayout} from './relation-viewport.mjs';
const read=key=>{try{const v=JSON.parse(localStorage.getItem(key));return {collapsed:v?.collapsed===true,ratio:Number.isFinite(v?.ratio)?Math.max(.2,Math.min(.6,v.ratio)):1/3};}catch{return {collapsed:false,ratio:1/3};}};
export function useRelationSidebar(novelId,mode,reveal){
 const key=relationSidebarKey(novelId,mode),[record,setRecord]=useState(()=>({key,...read(key)})),[width,setWidth]=useState(0),[mobileOpen,setMobileOpen]=useState(!!reveal),nodeRef=useRef(null),observerRef=useRef(null),drag=useRef(null);
 const value=record.key===key?record:{key,...read(key)};
 const update=patch=>setRecord(old=>{const next={...(old.key===key?old:{key,...read(key)}),...patch};try{localStorage.setItem(key,JSON.stringify(next));}catch{}return next;});
 useEffect(()=>{if(reveal){update({collapsed:false});setMobileOpen(true);}},[reveal,key]);
 const ref=useCallback(el=>{observerRef.current?.disconnect();observerRef.current=null;nodeRef.current=el;if(!el)return;const measure=()=>{if(nodeRef.current!==el)return;const next=Math.max(0,Math.floor(el.clientWidth));setWidth(previous=>previous===next?previous:next);};measure();const observer=new ResizeObserver(measure);observer.observe(el);observerRef.current=observer;},[]);
 const size=relationSidebarWidth(width,value.ratio),resize=x=>{const box=nodeRef.current?.getBoundingClientRect();if(box?.width)update({ratio:relationSidebarWidth(box.width,(box.right-x)/box.width)/box.width});};
 const layout=relationSidebarLayout(width),collapsed=layout==='pages'?!mobileOpen:value.collapsed;
 return {ref,layout,collapsed,style:{'--relation-sidebar-width':`${size}px`},toggle:()=>layout==='pages'?setMobileOpen(open=>!open):update({collapsed:!value.collapsed}),separator:{role:'separator',tabIndex:0,'aria-label':'调整人物关系侧栏宽度','aria-orientation':'vertical','aria-valuemin':280,'aria-valuemax':Math.max(280,width-440),'aria-valuenow':Math.round(size),onPointerDown:e=>{if(e.button!==0)return;e.preventDefault();e.stopPropagation();drag.current=e.pointerId;e.currentTarget.setPointerCapture(e.pointerId);},onPointerMove:e=>{if(drag.current===e.pointerId){e.preventDefault();e.stopPropagation();resize(e.clientX);}},onPointerUp:e=>{if(drag.current===e.pointerId){drag.current=null;e.stopPropagation();}},onPointerCancel:()=>{drag.current=null;},onLostPointerCapture:()=>{drag.current=null;},onKeyDown:e=>{if(['ArrowLeft','ArrowRight','Home'].includes(e.key)){e.preventDefault();update({ratio:e.key==='Home'?1/3:relationSidebarWidth(width,(size+(e.key==='ArrowLeft'?24:-24))/width)/width});}}}};
}
export function RelationSidebarToggle({sidebar}){const label=sidebar.collapsed?'展开人物关系':'收起人物关系';return <button type="button" className="relation-sidebar-toggle" aria-label={label} title={label} aria-expanded={!sidebar.collapsed} onClick={e=>{e.stopPropagation();sidebar.toggle();}}><svg aria-hidden="true" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d={sidebar.collapsed?'M15 5l-7 7 7 7':'M9 5l7 7-7 7'}/></svg></button>;}
export function RelationSidebarDivider({sidebar}){return <div className={`relation-sidebar-divider ${sidebar.collapsed?'is-collapsed':''}`}><div className="relation-sidebar-resize" {...sidebar.separator} title="拖动调整侧栏宽度；方向键微调，Home 恢复三分之一"/>{sidebar.collapsed&&<RelationSidebarToggle sidebar={sidebar}/>}<nav className="relation-page-navigation" aria-label="时间线分页"><button type="button" onClick={sidebar.toggle} aria-label={sidebar.collapsed?'查看人物关系':'返回时间线'}>{sidebar.collapsed?'人物关系 →':'‹ 返回时间线'}</button></nav></div>;}
